PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, industry TEXT NOT NULL CHECK(industry IN ('photo','food')), description TEXT NOT NULL DEFAULT '', address TEXT NOT NULL, contact TEXT NOT NULL, brand_color TEXT NOT NULL DEFAULT '#0c7d83', demo INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, platform_admin INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS memberships (user_id TEXT PRIMARY KEY REFERENCES users(id), tenant_id TEXT NOT NULL REFERENCES tenants(id), role TEXT NOT NULL CHECK(role IN ('owner','staff')));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), slug TEXT UNIQUE NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','paused','ended')), config TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, reviewed_revision INTEGER, created_at TEXT NOT NULL, UNIQUE(id,tenant_id));
CREATE INDEX IF NOT EXISTS campaign_tenant ON campaigns(tenant_id,status);
CREATE TABLE IF NOT EXISTS campaign_versions (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), tenant_id TEXT NOT NULL, revision INTEGER NOT NULL, config TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS booking_slots (id TEXT PRIMARY KEY, campaign_id TEXT NOT NULL REFERENCES campaigns(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>0), reserved_count INTEGER NOT NULL DEFAULT 0 CHECK(reserved_count>=0 AND reserved_count<=capacity));
CREATE TABLE IF NOT EXISTS bookings (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, campaign_id TEXT NOT NULL, slot_id TEXT NOT NULL REFERENCES booking_slots(id), contact_enc TEXT, status TEXT NOT NULL CHECK(status IN ('requested','confirmed','completed','canceled')), visitor_hash TEXT NOT NULL, request_key TEXT NOT NULL, request_digest TEXT NOT NULL, privacy_hash TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(campaign_id,visitor_hash,request_key), FOREIGN KEY(campaign_id,tenant_id) REFERENCES campaigns(id,tenant_id));
CREATE INDEX IF NOT EXISTS booking_tenant ON bookings(tenant_id,campaign_id,status);
CREATE TABLE IF NOT EXISTS voucher_rules (campaign_id TEXT PRIMARY KEY REFERENCES campaigns(id), tenant_id TEXT NOT NULL, quota INTEGER NOT NULL, daily_limit INTEGER NOT NULL, per_visitor_limit INTEGER NOT NULL, issued_count INTEGER NOT NULL DEFAULT 0 CHECK(issued_count>=0 AND issued_count<=quota), valid_until TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS vouchers (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, campaign_id TEXT NOT NULL, code_hash TEXT NOT NULL UNIQUE, visitor_hash TEXT NOT NULL, request_key TEXT NOT NULL, privacy_hash TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('issued','redeemed','revoked')), issued_at TEXT NOT NULL, redeemed_at TEXT, valid_until TEXT NOT NULL, UNIQUE(campaign_id,visitor_hash,request_key), FOREIGN KEY(campaign_id,tenant_id) REFERENCES campaigns(id,tenant_id));
CREATE INDEX IF NOT EXISTS voucher_tenant ON vouchers(tenant_id,campaign_id,status);
CREATE TABLE IF NOT EXISTS redemption_logs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, voucher_id TEXT, actor_id TEXT NOT NULL, result TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analytics_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, campaign_id TEXT NOT NULL, event_type TEXT NOT NULL, source TEXT NOT NULL, anon_id TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL, FOREIGN KEY(campaign_id,tenant_id) REFERENCES campaigns(id,tenant_id));
CREATE INDEX IF NOT EXISTS events_tenant ON analytics_events(tenant_id,campaign_id,event_type,created_at);
CREATE TABLE IF NOT EXISTS ai_generations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, campaign_id TEXT NOT NULL, input_digest TEXT NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL, output TEXT, error_code TEXT, tokens INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS consent_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, subject_ref TEXT NOT NULL, notice_version TEXT NOT NULL, purpose TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, tenant_id TEXT, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, resets_at INTEGER NOT NULL);
